  //   }),
  // image_1: yup
  //   .mixed()
  //   .required("Image is required")
  //   .test("fileSize", "Image is required", (value) => {
  //     if (typeof value === "string") return true;
  //     return !value || value.size <= 1024 * 1024 * 3; // 5MB
  //   })
  //   .test("fileType", "Unsupported file format", (value) => {
